size_t fn_19(const unsigned char *src, size_t src_len, uint64_t key, unsigned char *dst, size_t dst_len)
{
    size_t i;
    if (src_len > dst_len)
        return (size_t)-1;
    for (i = 0; i < src_len; i++)
    {
        unsigned char b = (key >> (i & 7) * 8) & 0xff;
        dst[i] = src[i] ^ i ^ ((b << 0) | (b >> 8 - 0));
    }
    return src_len;
}
